#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# One synthetic validation cycle: descriptor -> package -> build in the FISH image -> run under FISH -> pipeline -> verify.
# Usage: tests/synth/run_synth.sh <descriptor.json> [log_dir]      env: IMG (default fishwait28), DURATION (default from descriptor)
set -u
cd "$(dirname "$0")/../.."
DESC=$1; LD=${2:-$HOME/fish_traces/synth_runs}; mkdir -p "$LD"
IMG=${IMG:-autoware-dev-trt-a1000-fishwait28:latest}
NAME=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['name'])" "$DESC")
DUR=${DURATION:-$(python3 -c "import json,sys; print(int(json.load(open(sys.argv[1]))['deployment'].get('duration_s', 60)))" "$DESC")}
WS=$HOME/fish_synth/ws_$NAME
echo "[synth] $NAME -> $WS (image $IMG, ${DUR}s)"
python3 tests/synth/synth_emit.py "$DESC" -o "$WS/src" || exit 2
cp "$DESC" "$WS/descriptor.json"
# build against the overlay inside the image (ccache-friendly: the ws persists)
docker run --rm --entrypoint bash -v "$WS":/ws "$IMG" -c 'set +u; source /opt/ros/humble/setup.bash; source /root/trace_overlay_ws/install/setup.bash; set -u; cd /ws && colcon build --cmake-args -DCMAKE_BUILD_TYPE=RelWithDebInfo -DBUILD_TESTING=OFF -DCMAKE_EXPORT_COMPILE_COMMANDS=ON 2>&1 | tail -4' || exit 3
[ -d "$WS/install" ] || { echo "[synth] build failed"; exit 3; }
# static class analysis of the generated package — AFTER the build (compile_commands.json; before 2026-10-25 23:40 it ran first and saw 0 TUs on a fresh workspace) (source-level 'reads' relation = corroboration for pointer holds / timer readers)
docker run --rm --entrypoint bash -v "$WS":/ws -v "$PWD/scripts/source_flow":/sf:ro "$IMG" -c 'python3 /sf/source_flow.py --all --build /ws/build --src /ws/src --jobs 4 --out /ws/source_flow.json 2>&1 | tail -2' || echo "[synth] static analysis failed (continuing without source corroboration)"
# run under FISH: functional run (no timing gates), container shim + retention/stamp probes, lineage event in the base whitelist
printf 'synth_%s IMG=%s FISH_LAUNCH_CMD='"'"'ros2 launch %s synth.launch.py'"'"' FISH_APP_SECONDS=%s FISH_PRE_CMD='"'"'source /root/fish_synth/ws_%s/install/setup.bash'"'"' FISH_EXTRA_DOCKER_ARGS='"'"'-v %s/fish_synth:/root/fish_synth'"'"' FISH_CONTAINER_SHIM=1 FISH_EXTRA_EVENTS=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids FISH_CDDS_XML=0 FISH_KERNEL_SCHED=1\n' "$NAME" "$IMG" "$NAME" "$DUR" "$NAME" "$HOME" > "$LD/plan_$NAME.txt"
FISH_ALLOW_FORK=1 NIGHT_RUNS_NO_SPLIT=1 bash scripts/night_runs.sh "$LD" < "$LD/plan_$NAME.txt"
RUN=$(grep "^synth_$NAME " "$LD/night_runs.txt" | tail -1 | awk '{print $2}')
[ -d "$RUN/nsys_1" ] || { echo "[synth] run dir not found ($RUN)"; exit 4; }
S=$(basename "$(cat "$RUN/nsys_1/session.txt")")
echo "[synth] session $S (run $RUN)"
# map the static links onto this session's nodes/topics -> FISH_SOURCE_FLOW for the model (needs the session ingested first:
# the pipeline ingests, so run it once, map, then re-run model + extractor with the corroboration)
FISH_SOURCE_FLOW= bash scripts/post_run_pipeline.sh "$RUN/nsys_1" "$HOME/fish_traces/analysis_$S" > "$LD/pipeline_$NAME.log" 2>&1
if [ -f "$WS/source_flow.json" ]; then
  python3 scripts/source_flow/map_source_flow.py "$S" "$WS/source_flow.json" --out "$WS/flow_$S.json" > "$LD/map_$NAME.log" 2>&1 && \
  ( cd postprocess && FISH_SOURCE_FLOW="$WS/flow_$S.json" python3 model_improved_pg.py --session "$S" > "$HOME/fish_traces/analysis_$S/model.log" 2>&1 && \
    FISH_SOURCE_FLOW="$WS/flow_$S.json" python3 extract_fish_tasks.py "$S" -o "$HOME/fish_traces/analysis_$S/fish_tasks.json" --releases "$HOME/fish_traces/analysis_$S/releases.json" --show 6 > "$HOME/fish_traces/analysis_$S/fish_tasks.txt" 2> "$HOME/fish_traces/analysis_$S/fish_tasks.err" ) \
  || echo "[synth] source-flow mapping / corroborated model failed (see $LD/map_$NAME.log)"
fi
[ -f tests/synth/verify_synth.py ] && python3 tests/synth/verify_synth.py "$S" "$WS/descriptor.json" --tasks "$HOME/fish_traces/analysis_$S/fish_tasks.json" | tee "$LD/verify_$NAME.txt"
echo "[synth] done: $S"
